import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"MusicHud TuneWeave — CurseForge edition","description":"","frontmatter":{},"headers":[],"relativePath":"projects/music-hud-paper/README-CF.md","filePath":"projects/music-hud-paper/README-CF.md"}'),r={name:"projects/music-hud-paper/README-CF.md"};function i(s,e,d,l,u,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="musichud-tuneweave-—-curseforge-edition" tabindex="-1">MusicHud TuneWeave — CurseForge edition <a class="header-anchor" href="#musichud-tuneweave-—-curseforge-edition" aria-label="Permalink to &quot;MusicHud TuneWeave — CurseForge edition&quot;">​</a></h1><blockquote><p><strong>This is the feature-limited CurseForge edition.</strong> It only connects to an existing TuneWeave service. It does not install, update, start, or manage external programs. The project is fully open source; visit its <a href="https://github.com/MOPELotus/MusicHud-TuneWeave" target="_blank" rel="noreferrer">GitHub homepage</a> for source and other information. Music playback, lyrics, the HUD and shared queues remain available.</p></blockquote><p>MusicHud TuneWeave adds an in-game music browser, playback controls, synchronized lyrics and a configurable HUD. Play independently or join a shared queue with other players using compatible clients and a supported server or proxy plugin.</p><p>This is an independently maintained fork of <a href="https://github.com/Ephern/MusicHud" target="_blank" rel="noreferrer">MusicHud by Ephern / Etern</a>. It separates music-provider integration into TuneWeave, uses its own mod identity and data paths, and includes changes to shared playback, queue coordination and server/proxy integration. It retains upstream attribution and is distributed under LGPL-3.0.</p><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><p>Install the file for your Minecraft version and loader, together with its required dependencies. Fabric needs Fabric API and the appropriate ModernUI build. Most supported ModernUI Fabric builds also need Forge Config API Port; the project&#39;s 26.2 / 26.3 ModernUI fork does not. NeoForge needs the corresponding ModernUI build. Never install this mod alongside upstream MusicHud or a second edition of MusicHud TuneWeave.</p><p>For Minecraft 26.2 / 26.3, use the matching <a href="https://github.com/MOPELotus/ModernUI-MC/releases" target="_blank" rel="noreferrer">ModernUI 3.13.0.9 release</a>. Choose either the standard <code>-universal.jar</code> or the MiSans <code>-universal-misans.jar</code> for your loader; replace the old ModernUI JAR and never install both editions. Standard supports custom fonts without a MiSans installer. MiSans retains its font installer and weight controls; missing fonts require an explicit download and restart. Both editions include the same marquee/render/input fixes and use separate client configuration files, importing the old <code>client.toml</code> on first use. See the <a href="https://github.com/MOPELotus/ModernUI-MC/blob/26.3-3.13.0.9/docs/font-editions.md" target="_blank" rel="noreferrer">font edition guide</a>. This font choice is independent of the MusicHud standard/CF distribution.</p><p>Press <strong>M</strong> in a world to open the music interface. Search for music, add tracks to the queue, or use a supported playlist as an idle playback source. Lyrics, account features and available audio quality depend on the music service and the user&#39;s access rights.</p><h3 id="external-music-service" tabindex="-1">External music service <a class="header-anchor" href="#external-music-service" aria-label="Permalink to &quot;External music service&quot;">​</a></h3><p>Install and start TuneWeave independently, outside the mod. Enter the service address in Settings (usually <code>http://127.0.0.1:7832</code>). This edition has no executable-path settings, program acquisition, automatic startup, child-process controls or process-log management. Audio playback and system media integration still use bundled native libraries.</p><p>CF service preferences use a separate <code>musichud_tuneweave-cf-server.toml</code> file, preserving the standard edition&#39;s process configuration when switching editions. Only install one edition at a time.</p><h3 id="multiplayer" tabindex="-1">Multiplayer <a class="header-anchor" href="#multiplayer" aria-label="Permalink to &quot;Multiplayer&quot;">​</a></h3><p>Players need the client mod and its dependencies. A standalone Paper server uses the Paper plugin. Velocity and BungeeCord networks install the matching plugin <strong>only on the proxy</strong>, with no copy on any backend. The plugins coordinate public playback and do not run TuneWeave or store music-platform login credentials.</p><h3 id="support-and-development" tabindex="-1">Support and development <a class="header-anchor" href="#support-and-development" aria-label="Permalink to &quot;Support and development&quot;">​</a></h3><p>Please report reproducible problems with Minecraft, loader, mod and TuneWeave versions at the linked issue tracker. Remove credentials from logs before sharing them. The project is maintained by MOPELotus.</p><h2 id="中文说明" tabindex="-1">中文说明 <a class="header-anchor" href="#中文说明" aria-label="Permalink to &quot;中文说明&quot;">​</a></h2><p>这是 CurseForge 精简版，仅连接已有 TuneWeave 服务，不负责外部程序的安装、更新、启动或管理。请自行在模组外安装并启动 TuneWeave，然后在设置中填写服务地址。音乐播放、歌词、HUD 和共享队列仍可使用。普通版与 CF 版使用同一模组标识和协议，请只安装其中一种。</p><h2 id="edition-notice-and-mod-updates" tabindex="-1">Edition notice and mod updates <a class="header-anchor" href="#edition-notice-and-mod-updates" aria-label="Permalink to &quot;Edition notice and mod updates&quot;">​</a></h2><p>The first MusicHud screen explains the CF edition once. “Take a look” opens only the GitHub project homepage to view source and other content. “Understood” saves acknowledgement, so the notice does not repeat. Users who acknowledged the earlier notice see this changed connection-only policy once.</p><p>Version checks remain available, including matching releases and prereleases. A new-version notice offers the project-home link and “Later”; it never downloads or installs files or opens a Release download page. “Later” suppresses automatic reminders for that version during the current game process. A manual check can show it again. Manual checks show checking, current and failed states; background check failures do not open a dialog.</p><p>首次打开模组 UI 时显示一次「CF 精简版」说明。「去看看」仅打开 GitHub 项目主页，查看源码及其他项目内容，不自动下载或安装文件。「知道了」保存确认记录，以后不再重复提示。此前确认过旧说明的用户会看到一次新的连接模式说明。</p><p>发现新版本时，仅告知版本状态。「去看看」打开项目主页，「下次再说」使同一版本在本次游戏进程内不再自动提醒；手动检查仍可重新显示。手动检查显示「正在检查」「没有匹配的新版本」「检查失败」等状态，后台检查失败不主动弹窗。GitHub 普通发行版继续保留完整的 TuneWeave 管理能力。</p>',22)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
